    "vllm/lora/ops/sgmv_expand.py": {
        "_sgmv_expand_kernel": "@triton.jit\ndef _sgmv_expand_kernel(\n    input_ptr,\n    lora_ptr,\n    out_ptr,\n    N,\n    K,\n    b_seq_start_loc,\n    seq_lens,\n    lora_indices,\n    slice_start_loc,\n    input_d0_stride,\n    input_d1_stride,\n    input_d2_stride,\n    ls_d0_ptr,\n    ls_d1_ptr,\n    ls_d2_ptr,\n    output_d0_stride,\n    output_d1_stride,\n    output_hs_ptr,\n    BLOCK_M: tl.constexpr,\n    BLOCK_N: tl.constexpr,\n    BLOCK_K: tl.constexpr,\n    EVEN_K: tl.constexpr,\n    ADD_INPUTS: tl.constexpr,\n    CAST_TYPE: tl.constexpr,\n    SLICE_NUM: tl.constexpr,\n    SAME_STRIDE: tl.constexpr):\n    \"\"\"\n    The sgmv's expand triton kernel is based on GroupGEMM.\n    This kernel supports 1-3 subLoRAs (slices) in a single call.\n    \"\"\"\n    pid = tl.program_id(axis=0)\n    cur_batch = tl.program_id(axis=1)\n    cta_n_num = tl.cdiv(N, BLOCK_N)\n    pid_m = pid // cta_n_num\n    pid_n = pid % cta_n_num\n    M = tl.load(seq_lens + cur_batch)\n    if pid_m * BLOCK_M > M:\n        return\n    lora_index = tl.load(lora_indices + cur_batch)\n    if lora_index == -1:\n        return\n    cur_seq_start = tl.load(b_seq_start_loc + cur_batch)\n    offset_m = tl.arange(0, BLOCK_M) + pid_m * BLOCK_M\n    offset_n = tl.arange(0, BLOCK_N) + pid_n * BLOCK_N\n    offset_k = tl.arange(0, BLOCK_K)\n    ram = tl.max_contiguous(tl.multiple_of(offset_m % M, BLOCK_M), BLOCK_M)\n    rbn = tl.max_contiguous(tl.multiple_of(offset_n % N, BLOCK_N), BLOCK_N)\n\n    # Load strides for this lora_index\n    if SLICE_NUM > 1 and not SAME_STRIDE:\n        lora_d0 = tl.load(ls_d0_ptr + lora_index)\n        lora_d1 = tl.load(ls_d1_ptr + lora_index)\n        lora_d2 = tl.load(ls_d2_ptr + lora_index)\n    else:\n        lora_d0 = ls_d0_ptr\n        lora_d1 = ls_d1_ptr\n        lora_d2 = ls_d2_ptr\n\n    # Process each slice\n    for slice_idx in range(SLICE_NUM):\n        # Load slice start location\n        if SLICE_NUM > 1:\n            slice_offset = tl.load(slice_start_loc + slice_idx)\n        else:\n            slice_offset = slice_start_loc\n\n        # Compute input pointer\n        a_ptr = (input_ptr + cur_seq_start * input_d0_stride +\n                 ram[:, None] * input_d0_stride +\n                 offset_k[None, :] * input_d1_stride)\n\n        # Load lora base pointer for this slice\n        if SLICE_NUM > 1:\n            lora_base_ptr = tl.load(lora_ptr + slice_idx)\n        else:\n            lora_base_ptr = lora_ptr\n\n        # Compute lora pointer\n        b_ptr = (lora_base_ptr + lora_d0 * lora_index +\n                 offset_k[:, None] * lora_d2 + rbn[None, :] * lora_d1)\n\n        accumulator = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)\n        for k in range(tl.cdiv(K, BLOCK_K)):\n            if EVEN_K:\n                tiled_a = tl.load(a_ptr)\n                tiled_b = tl.load(b_ptr)\n            else:\n                tiled_a = tl.load(a_ptr,\n                                  mask=offset_k[None, :] < K - k * BLOCK_K,\n                                  other=0)\n                tiled_b = tl.load(b_ptr,\n                                  mask=offset_k[:, None] < K - k * BLOCK_K,\n                                  other=0)\n            if CAST_TYPE:\n                tiled_a = tiled_a.to(lora_base_ptr.dtype.element_ty)\n            accumulator += tl.dot(\n                tiled_a,\n                tiled_b,\n            )\n            a_ptr += BLOCK_K * input_d1_stride\n            b_ptr += BLOCK_K * lora_d2\n\n        tiled_c = accumulator.to(lora_base_ptr.dtype.element_ty)\n        offset_cm = cur_seq_start + tl.arange(0, BLOCK_M) + pid_m * BLOCK_M\n        offset_cn = slice_offset + tl.arange(0, BLOCK_N) + pid_n * BLOCK_N\n\n        # Compute output pointer\n        c_ptr = (out_ptr + offset_cm[:, None] * output_d0_stride +\n                 offset_cn[None, :] * output_d1_stride)\n\n        M = tl.load(seq_lens + cur_batch)\n        c_mask = (offset_cm[:, None] <\n                  (cur_seq_start + M)) & (offset_cn[None, :] < N)\n\n        if ADD_INPUTS:\n            # explicitly pass in other=None to tell triton that masked values\n            # can be uninitialized. This is OK because the later tl.store operation\n            # uses the same mask, eliminating the risk of garbage values propagating\n            tiled_out = tl.load(c_ptr, mask=c_mask, other=None)\n            tiled_c += tiled_out\n        tl.store(c_ptr, tiled_c, mask=c_mask)",
        "_sgmv_expand": "@torch.inference_mode()\ndef _sgmv_expand(\n    inputs: torch.Tensor,\n    lora_b_weights: List[torch.Tensor],\n    output_tensor: torch.Tensor,\n    b_seq_start_loc: torch.Tensor,\n    seq_len_tensor: torch.Tensor,\n    lora_indices_tensor: torch.Tensor,\n    batches: int,\n    max_seq_length: int,\n    token_nums: int,\n    offset_start: int = 0,\n    add_inputs: bool = False,\n) -> None:\n    \"\"\"\n    Args:\n        inputs (torch.Tensor): input tensor\n        lora_b_weights (List[torch.Tensor]): list of lora'b weights for each slice\n        output_tensor (torch.Tensor): output tensor\n        b_seq_start_loc (torch.Tensor): (batch_size,). The cumulative\n            sequence lengths of the sequences in the batch, used to index\n            into sequence. E.g., if the sequence length is [4, 6], it is\n            [0, 4, 10].\n        seq_len_tensor (torch.Tensor): (batch_size,). Record the sequence\n            length of the sequences in the batch.\n        lora_indices_tensor (torch.Tensor): (batch_size,). The LoRA index\n            corresponding to each batch. An index of -1 means no lora should be\n            applied.\n        batches (int): batch size\n        max_seq_length (int): The max sequence lengths of the sequences in the \n            batch.\n        token_nums (int): The token numbers in the batch. Used to verify if the \n            token numbers in the inputs matches the one in the metadata.\n        offset_start (int, optional): Defaults to 0, the starting offset for output.\n        add_inputs (bool, optional): Defaults to False, adds the final lora \n            results to the output.\n    \"\"\"\n\n    assert inputs.dtype in [torch.float16, torch.bfloat16, torch.float32]\n    assert lora_b_weights[0].dtype in [\n        torch.float16,\n        torch.bfloat16,\n    ]\n    assert inputs.size(0) == token_nums\n    assert inputs.size(1) == lora_b_weights[0].size(-1)\n    assert b_seq_start_loc.size(0) == batches\n   