        "_sgmv_shrink": "@torch.inference_mode()\ndef _sgmv_shrink(\n    inputs: torch.Tensor,\n    lora_a_weights: List[torch.Tensor],\n    output_tensor: torch.Tensor,\n    b_seq_start_loc: torch.Tensor,\n    seq_len_tensor: torch.Tensor,\n    lora_indices_tensor: torch.Tensor,\n    batches: int,\n    max_seq_length: int,\n    token_nums: int,\n    scaling: float,\n) -> None:\n    \"\"\"\n\n    Args:\n        inputs (torch.Tensor): input tensor\n        lora_a_weights (List[torch.Tensor]): list of lora'a weights for each slice\n        output_tensor (torch.Tensor): output tensor\n        b_seq_start_loc (torch.Tensor): (batch_size,). The cumulative\n            sequence lengths of the sequences in the batch, used to index\n            into sequence. E.g., if the sequence length is [4, 6], it is\n            [0, 4].\n        seq_len_tensor (torch.Tensor): (batch_size,). Record the sequence\n            length of the sequences in the batch.\n        lora_indices_tensor (torch.Tensor): (batch_size,). The LoRA index\n            corresponding to each batch. An index of -1 means no lora should be\n            applied.\n        batches (int): batch size\n        max_seq_length (int): The max sequence lengths of the sequences in the \n            batch.\n        token_nums (int): The token numbers in the batch. Used to verify if the \n            token numbers in the inputs matches the one in the metadata.\n        scaling (float): Scaling factor.\n    \"\"\"\n    assert inputs.dtype == lora_a_weights[0].dtype\n    assert inputs.dtype in [torch.float16, torch.bfloat16]\n    assert lora_a_weights[0].dtype in [\n        torch.float16,\n        torch.bfloat16,\n    ]\n    assert inputs.size(0) == token_nums\n    assert inputs.size(1) == lora_a_weights[0].size(-1)\n    assert b_seq_start_loc.size(0) == batches\n    assert lora_indices_tensor.size(0) == batches\n    assert inputs.is_contiguous()\n\n    SLICE_NUM = len(lora_a_weights)\n    assert 1 <= SLICE_NUM <= 3, \"SLICE_NUM must be 1, 2, or 3\"\n\n    # Get lora pointers and strides\n    lora_ptr_tensor, lora_d0, lora_d1, lora_d2 = _get_lora_a_ptr(\n        lora_a_weights, str(inputs.device))\n\n    # Get N and K from first slice (all slices should have same shape)\n    N, K = lora_a_weights[0].shape[-2:]  # K=hidden_size,N=rank\n    \n    BLOCK_M = 32\n    BLOCK_N = 16\n    BLOCK_K = 32\n    SPLIT_K = 8\n    EVEN_K = K % (BLOCK_K * SPLIT_K) == 0\n    grid = (\n        triton.cdiv(max_seq_length, BLOCK_M) * triton.cdiv(N, BLOCK_N),\n        SPLIT_K,\n        batches,\n    )\n\n    _sgmv_shrink_kernel[grid](\n        inputs,\n        lora_ptr_tensor,\n        output_tensor,\n        N,\n        K,\n        b_seq_start_loc,\n        seq_len_tensor,\n        lora_indices_tensor,\n        scaling,\n        inputs.stride(0),\n        inputs.stride(1),\n        lora_d0,\n        lora_d1,\n        lora_d2,\n        output_tensor.stride(0),\n        output_tensor.stride(1),\n        BLOCK_M,\n        BLOCK_N,\n        BLOCK_K,\n        EVEN_K,\n        SPLIT_K,\n        SLICE_NUM,\n    )\n    return"
